<template>
  <div v-loading="loading" :class="['after-sale-settings',{'app-container':!embedded}]">
    <template v-if="!channelId">
      <div class="page-heading"><div><h2>售后设置</h2><p class="hint">按店铺维护退款接入、平台授权、自动处理和退货入库规则。</p></div><el-button size="small" icon="el-icon-refresh" @click="loadList">刷新配置状态</el-button></div>
      <div class="overview-cards"><button v-for="item in presets" :key="item.value" :class="{active:query.status===item.value}" @click="preset(item.value)"><span>{{ item.label }}</span><strong>{{ summary[item.key] || 0 }}</strong></button></div>
      <el-form inline size="small" @submit.native.prevent="search"><el-form-item label="店铺"><el-input v-model.trim="query.keyword" clearable placeholder="店铺名称 / 渠道 ID" @keyup.enter.native="search" /></el-form-item><el-form-item label="配置状态"><el-select v-model="query.status" clearable><el-option v-for="item in presets.filter(p=>p.value)" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item><el-form-item><el-button type="primary" @click="search">查询</el-button><el-button @click="resetSearch">重置</el-button></el-form-item></el-form>
      <el-alert v-if="capabilityUnavailable" title="平台授权状态暂不可用，接入及仓库配置仍可查看。请刷新后核对授权条件。" type="warning" :closable="false" show-icon />
      <el-table :data="rows" row-key="channel_id" empty-text="没有符合筛选的店铺">
        <el-table-column label="店铺" min-width="195"><template slot-scope="s"><strong>{{ s.row.channel_name }}</strong><p class="hint">天猫 · 渠道 {{ s.row.channel_id }}</p><el-tag v-if="!Number(s.row.shop_enabled)" size="mini" type="info">店铺已停用</el-tag></template></el-table-column>
        <el-table-column label="退款接入" min-width="190"><template slot-scope="s"><span :class="{'warning':s.row.sync_error}">{{ s.row.overview.intake }}</span><p class="hint">JDP {{ Number(s.row.intake.enabled)?'开启':'关闭' }} · 接口补充 {{ Number(s.row.api_sync.enabled)?'开启':'关闭' }}</p></template></el-table-column>
        <el-table-column label="平台授权与权限" min-width="215"><template slot-scope="s">{{ s.row.overview.access }}<p class="hint">实际付款权限 {{ Number(s.row.access.payment_enabled)?'允许':'关闭' }}</p></template></el-table-column>
        <el-table-column label="自动处理" min-width="185"><template slot-scope="s">{{ s.row.overview.automation }}<p v-if="s.row.overview.waiting.length" class="warning">{{ s.row.overview.waiting.length }} 项待满足条件</p></template></el-table-column>
        <el-table-column label="退货与入库" min-width="190"><template slot-scope="s">{{ s.row.overview.returns }}<p class="hint">退回安排：{{ Number(s.row.returns.auto_create)?'自动创建':'人工创建' }}</p></template></el-table-column>
        <el-table-column label="当前问题" min-width="230"><template slot-scope="s"><el-button v-if="s.row.checks.length" type="text" class="issue-link" @click="openShop(s.row.channel_id,s.row.checks[0].tab)">{{ s.row.checks[0].message }}{{ s.row.checks.length>1?' 等'+s.row.checks.length+'项':'' }}</el-button><span v-else-if="s.row.sync_error" class="warning">{{ s.row.intake.last_error || s.row.api_sync.last_error }}</span><span v-else class="hint">{{ s.row.configured?'暂无本地配置问题':'尚未配置' }}</span></template></el-table-column>
        <el-table-column label="操作" fixed="right" width="85"><template slot-scope="s"><el-button type="text" @click="openShop(s.row.channel_id)">配置</el-button></template></el-table-column>
      </el-table>
      <pagination v-show="total>0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @pagination="loadList" />
    </template>
    <template v-else-if="model">
      <div v-if="!embedded" class="page-heading"><div><el-button type="text" icon="el-icon-back" @click="backToList">全部店铺</el-button><h2>{{ model.channel_name }} <el-tag size="small" :type="dirty?'warning':'info'">{{ dirty?'有未保存修改':'已读取保存配置' }}</el-tag></h2><p class="hint">天猫 · 渠道 {{ channelId }}<span v-if="!Number(model.shop_enabled)" class="warning"> · 店铺已停用，仅供查看</span></p></div><div><el-button v-if="refundId" size="small" @click="backToRefund">返回退款单</el-button><el-button size="small" :disabled="saving" @click="reloadEditor">重新读取配置状态</el-button></div></div>
      <div v-if="!embedded" class="shop-switch"><span>切换店铺</span><el-select :value="channelId" filterable remote :remote-method="searchShops" :loading="shopLoading" placeholder="搜索店铺名称或渠道 ID" size="small" @visible-change="shown=>shown&&searchShops('')" @change="id=>openShop(id,tab)"><el-option v-for="shop in shopOptions" :key="shop.channel_id" :label="shop.channel_name" :value="String(shop.channel_id)" /></el-select></div>
      <section v-if="!embedded" class="flow-summary"><strong>{{ dirty?'按当前修改预览处理流程':'当前配置的处理流程' }}</strong><p>{{ overview.flow.join(' → ') }}</p><span class="hint">以下条件按本地配置判断；每张退款仍须检查平台允许操作、货物状态及金额。仓库能力在“退货与入库”中核对。</span></section>
      <el-tabs v-if="!embedded" v-model="tab" :before-leave="beforeTabLeave">
        <el-tab-pane v-for="item in tabs" :key="item.name" :label="item.label+(tab===item.name&&dirty?' · 未保存':'')" :name="item.name" />
      </el-tabs>
      <el-alert v-if="error" :title="error" type="error" show-icon :closable="false" />
      <div v-if="tab!=='returns'" class="configuration-layout">
        <section class="configuration-form">
          <template v-if="tab==='intake'">
            <el-alert title="退款同步、转业务单与自动处理分别控制。开启同步不会同意退款或执行付款。" type="info" :closable="false" show-icon />
            <el-form label-width="155px" size="small" :disabled="saving||!Number(model.shop_enabled)">
              <h3>JDP推送同步</h3><p class="hint">需要推送同步时填写来源资料；只调整接口补充同步时无需改动本节。</p>
              <el-form-item label="推送库"><el-select v-model="model.intake.source_key" :disabled="!!Number(model.intake.revision)" placeholder="选择推送来源"><el-option v-for="s in model.sources" :key="s.key" :value="s.key" :label="s.label" :disabled="!s.enabled" /></el-select><p class="hint">连接资料在<router-link v-hasPermi="['order:source:config']" :to="{path:'/oms-order/businessSettings',query:{scope:'sources'}}">推送库配置</router-link>中维护。</p></el-form-item>
              <el-form-item label="推送库卖家昵称"><el-input v-model.trim="model.intake.seller_nick" :disabled="!!Number(model.intake.revision)" maxlength="200" /></el-form-item>
              <el-form-item label="首次同步时间"><el-date-picker v-model="model.intake.initial_time" :disabled="!!Number(model.intake.revision)" type="datetime" value-format="yyyy-MM-dd HH:mm:ss" /><p class="hint">首次保存后固定；需要补拉时在同步任务创建补拉。</p></el-form-item>
              <el-form-item label="自动同步"><el-switch v-model="model.intake.enabled" :active-value="1" :inactive-value="0" /></el-form-item>
              <el-form-item label="自动转业务退款"><el-switch v-model="model.intake.auto_convert" :active-value="1" :inactive-value="0" /></el-form-item>
              <el-form-item label="扫描间隔"><el-input-number v-model="model.intake.interval_seconds" :min="10" :max="3600" :precision="0" /> 秒</el-form-item>
              <p class="hint">最近成功：{{ model.intake.last_success||'尚无记录' }} · 同步游标：{{ model.intake.cursor_time||'尚未开始' }}</p><p v-if="model.intake.last_error" class="warning">{{ model.intake.last_error }}</p>
              <el-button v-if="Number(model.intake.revision)" size="small" :loading="checking" @click="checkJdp">检查推送库读取能力</el-button>
              <h3>普通退款官方接口补充同步</h3><el-form-item label="补充同步"><el-switch v-model="model.api_sync.enabled" :active-value="1" :inactive-value="0" /><p class="hint">独立于JDP同步及自动处理开关；完整详情由后台任务保存。专项退款需对应专项接入。</p></el-form-item>
              <p class="hint">最近列表保存：{{ model.api_sync.last_success||'尚无记录' }} · 游标：{{ model.api_sync.cursor_time||'启用时开始' }}</p><p v-if="model.api_sync.last_error" class="warning">{{ model.api_sync.last_error }}</p><p v-for="count in model.api_sync.detail_counts||[]" :key="count.state" class="hint">详情{{ count.state==='FAILED'?'待重试':'待处理' }}：{{ count.quantity }} 条</p><p v-for="item in model.api_sync.detail_errors||[]" :key="item.refund_id" class="warning">{{ item.refund_id }}：{{ item.last_error }}</p>
            </el-form>
          </template>
          <template v-if="tab==='authorization'">
            <el-alert title="授权和权限决定OMS可以调用哪些接口；自动执行由“自动处理”页签单独控制。" type="info" :closable="false" show-icon />
            <el-descriptions :column="1" size="small" border><el-descriptions-item label="主账号授权">{{ model.access.authorization||'状态未取得' }} · {{ model.access.authorization_expires_at||'未提供到期时间' }}</el-descriptions-item><el-descriptions-item label="付款子账号">{{ model.access.payment_authorized?'授权有效':'尚未授权或已过期' }}<span v-if="model.access.payment_expires_at"> · {{ model.access.payment_expires_at }}</span></el-descriptions-item></el-descriptions>
            <div class="authorization-actions"><el-button v-hasPermi="['channel:platform:query']" size="small" @click="openMainAuthorization">查看店铺主授权</el-button><el-button v-hasPermi="['channel:platform:authorize']" size="small" :disabled="!Number(model.shop_enabled)" :loading="authorizing" @click="authorizePayment">授权本店铺付款子账号</el-button></div>
            <el-form label-width="175px" size="small" :disabled="saving||!Number(model.shop_enabled)||model.access.available===false"><el-form-item label="允许查询普通退款"><el-switch v-model="model.access.read_enabled" :active-value="1" :inactive-value="0" /></el-form-item><el-form-item label="允许提交售后操作"><el-switch v-model="model.access.write_enabled" :active-value="1" :inactive-value="0" /><p class="hint">依赖退款查询权限。</p></el-form-item><el-form-item label="允许实际退款付款"><el-switch v-model="model.access.payment_enabled" :active-value="1" :inactive-value="0" /><p class="hint">依赖查询及售后操作权限；实际付款还要核对有效子账号与验证码条件。</p></el-form-item><el-form-item label="平台免短信验证码"><el-switch v-model="model.access.ignore_code" :active-value="1" :inactive-value="0" /><el-checkbox v-if="Number(model.access.ignore_code)" v-model="model.access.ignore_code_confirmed">商家已在平台明确开通免验证码</el-checkbox></el-form-item></el-form>
            <el-alert v-if="model.access.available===false" title="授权配置读取失败，当前无法修改；请重新读取配置状态。" type="warning" :closable="false" />
          </template>
          <refund-flow-settings v-if="tab==='automation'" v-model="model.flow" :disabled="saving||!Number(model.shop_enabled)" :addresses="addresses" :address-loading="addressLoading" @addresses="loadAddresses" />
        </section>
        <aside class="effect-panel"><strong>{{ dirty?'当前修改的生效条件':'已保存配置的生效条件' }}</strong><p class="hint">仅展示本页相关动作。未开启的动作不会执行。</p><div v-for="check in displayedChecks" :key="check.id" class="effect-item"><div><b>{{ check.label }}</b><el-tag size="mini" :type="check.state==='READY'?'success':check.state==='WAIT'?'warning':'info'">{{ ({READY:'配置条件已满足',WAIT:'条件未满足',OFF:'未开启'})[check.state] }}</el-tag></div><template v-if="check.requested"><p v-for="g in check.gates" :key="g.label" :class="g.ok?'hint':'warning'"><i :class="g.ok?'el-icon-check':'el-icon-warning-outline'" /> {{ g.label }}<el-button v-if="!g.ok&&g.tab!==tab" type="text" @click="navigateTab(g.tab)">去配置</el-button></p></template></div></aside>
      </div>
      <section v-if="tab==='returns'" class="return-config"><el-alert title="平台退回地址用于告知买家；本页退回仓及地址用于仓库接单、实收和库存入账，请核对一致。" type="info" :closable="false" show-icon /><refund-parcel-settings ref="returns" :read-only="!Number(model.shop_enabled)" @dirty="returnDirty=$event" @busy="returnBusy=$event" @saving="returnSaving=$event" @loaded="returnLoaded" @preview="returnPreview" @changed="returnSaved" /></section>
      <div v-if="tab!=='returns'" class="save-bar"><span class="hint">{{ dirty?'当前页签有未保存修改':'当前显示已保存配置；实际执行仍按单据条件核对' }}</span><div><el-button :disabled="saving" @click="reloadEditor">重新加载</el-button><el-button type="primary" :disabled="!dirty||saving||!Number(model.shop_enabled)||(tab==='authorization'&&model.access.available===false)" :loading="saving" @click="save">保存{{ currentTabLabel }}</el-button></div></div>
    </template>
    <el-alert v-else-if="!loading" :title="error||'配置加载失败，请重试'" type="error" show-icon :closable="false"><el-button size="small" @click="loadEditor">重新加载</el-button></el-alert>
  </div>
</template>
<script>
import request from '@/utils/request'
import { parseTime } from '@/utils/ruoyi'
import { saveRefundConfig, testRefundConfig } from '@/api/order/refund'
import RefundFlowSettings from './RefundFlowSettings'
import RefundParcelSettings from './RefundParcelSettings'
import { configurationChecks, configurationOverview, settingsTabs, settingsPath } from './refundConfigurationPresentation'
const clone = value => JSON.parse(JSON.stringify(value))
const presets = [{ value: '', label: '全部店铺', key: 'shops' }, { value: 'UNCONFIGURED', label: '未配置', key: 'unconfigured' }, { value: 'INCOMPLETE', label: '条件未满足', key: 'incomplete' }, { value: 'AUTOMATIC', label: '自动处理已开启', key: 'automatic' }, { value: 'ERROR', label: '同步异常', key: 'errors' }]
export default {
  name: 'RefundAfterSaleSettings', props: { embedded: Boolean, channel: [String, Number], selectedTab: { type: String, default: 'intake' } }, components: { RefundFlowSettings, RefundParcelSettings },
  beforeRouteLeave(to, from, next) { this.canDiscard().then(ok => next(ok)) },
  beforeRouteUpdate(to, from, next) { if (String(to.query.channelId || '') !== String(from.query.channelId || '')) this.canDiscard().then(ok => next(ok)); else if (String(to.query.tab || 'intake') !== this.tab) this.allowTab(to.query.tab || 'intake', this.tab).then(ok => next(ok)); else next() },
  data: () => ({ loading: false, saving: false, checking: false, authorizing: false, addressLoading: false, shopLoading: false, error: '', rows: [], total: 0, summary: {}, capabilityUnavailable: false, query: { keyword: '', status: '', pageNum: 1, pageSize: 20 }, presets, tabs: settingsTabs, tab: 'intake', model: null, saved: null, returnDirty: false, returnBusy: false, returnSaving: false, addresses: [], shopOptions: [], sequence: 0, shopSequence: 0 }),
  computed: {
    channelId() { return String(this.embedded ? this.channel || '' : this.$route.query.channelId || '') }, refundId() { return this.$route.query.refundId },
    dirty() { if (!this.model || !this.saved) return false; return this.tab === 'returns' ? this.returnDirty : this.serial(this.model, this.tab) !== this.serial(this.saved, this.tab) },
    checks() { return this.model ? configurationChecks(this.model) : [] }, overview() { return configurationOverview(this.model || {}) }, currentTabLabel() { return (this.tabs.find(t => t.name === this.tab) || {}).label || '' },
    displayedChecks() { return this.checks.filter(c => this.tab === 'authorization' ? ['api', 'agree', 'review', 'pay', 'feedback', 'intercept'].includes(c.id) : this.tab === 'intake' ? c.id === 'api' : !['api', 'create', 'merge', 'dispatch'].includes(c.id)) }
  },
  watch: { dirty: { immediate: true, handler(value) { this.$emit('dirty',value) } }, saving(value) { this.$emit('busy',value); this.$emit('saving',value) }, returnSaving(value) { this.$emit('busy',value); this.$emit('saving',value) }, channel() { if (this.embedded) this.routeChanged() }, selectedTab() { if (this.embedded) this.routeChanged() }, '$route.fullPath'() { if (!this.embedded) this.routeChanged() }, tab() { if (!this.embedded && this.model && String(this.model.channel_id) === this.channelId) this.tabChanged() } },
  created() { if (!this.embedded) { const map = { intake:'refund-intake',authorization:'platform',automation:'refund-automation',returns:'refund-returns' }; this.$router.replace({path:'/oms-order/businessSettings',query:{...this.$route.query,section:map[this.$route.query.tab]||'refund-intake'}}) } else this.routeChanged() }, mounted() { if (!this.embedded) window.addEventListener('beforeunload', this.beforeUnload) }, beforeDestroy() { this.sequence++; this.shopSequence++; window.removeEventListener('beforeunload', this.beforeUnload) },
  methods: {
    serial(model, tab) { if (tab === 'intake') return JSON.stringify([model.intake.source_key, model.intake.seller_nick, model.intake.initial_time, model.intake.enabled, model.intake.auto_convert, model.intake.interval_seconds, model.api_sync.enabled]); return JSON.stringify(model[tab === 'authorization' ? 'access' : 'flow']) },
    async canDiscard() { if (this.saving || this.returnSaving) return false; if (!this.dirty) return true; try { await this.$confirm('当前页签有未保存修改，是否放弃修改并离开？', '未保存修改', { confirmButtonText: '放弃修改', cancelButtonText: '继续编辑', type: 'warning' }); return true } catch (_) { return false } },
    beforeUnload(event) { if (this.dirty || this.saving || this.returnSaving) { event.preventDefault(); event.returnValue = '' } },
    beforeTabLeave(next, old) { return this.allowTab(next, old).then(allowed => { if (!allowed) throw new Error('当前修改尚未保存') }) },
    async allowTab(next, old) { if (next === old) return true; if (!(await this.canDiscard())) return false; if (this.model && this.saved) { this.model = clone(this.saved); this.returnDirty = false } return true },
    async navigateTab(tab) { if (this.embedded) { this.$emit('navigate', {intake:'refund-intake',authorization:'platform',automation:'refund-automation',returns:'refund-returns'}[tab]); return } if (await this.allowTab(tab, this.tab)) { this.tab = tab } },
    tabChanged() { this.error = ''; this.$router.replace({ path: settingsPath, query: { ...this.$route.query, tab: this.tab }}).catch(() => {}); this.loadReturnTab() },
    routeChanged() { const requested = this.embedded ? this.selectedTab : this.$route.query.tab; const next = this.tabs.some(t => t.name === requested) ? requested : 'intake'; this.tab = next; if (!this.channelId) { this.model = null; this.saved = null; this.loadList() } else if (!this.model || String(this.model.channel_id) !== this.channelId) this.loadEditor(); else this.loadReturnTab() },
    async loadList() { const seq = ++this.sequence; this.loading = true; this.error = ''; try { const data = (await request({ url: '/order/refunds/settings', params: this.query })).data; if (seq !== this.sequence) return; this.rows = data.rows.map(row => ({ ...row, overview: configurationOverview(row) })); this.total = Number(data.total); this.summary = data.summary; this.capabilityUnavailable = data.capability_unavailable } catch (_) { if (seq === this.sequence) { this.rows = []; this.total = 0; this.$message.error('售后配置列表读取失败，请重试') } } finally { if (seq === this.sequence) this.loading = false } },
    search() { this.query.pageNum = 1; return this.loadList() }, preset(value) { this.query.status = value; return this.search() }, resetSearch() { this.query = { keyword: '', status: '', pageNum: 1, pageSize: 20 }; return this.loadList() },
    openShop(channel, tab = 'intake') { if (String(channel) === this.channelId) return this.navigateTab(tab); return this.$router.push({ path: settingsPath, query: { channelId: String(channel), tab, ...(this.refundId ? { refundId: this.refundId } : {}) }}) },
    backToList() { return this.$router.push({ path: settingsPath }) }, backToRefund() { return this.$router.push({ path: '/oms-order/businessRefunds', query: { id: this.refundId }}) },
    async searchShops(keyword) { const seq = ++this.shopSequence; this.shopLoading = true; try { const data = (await request({ url: '/order/refunds/settings', params: { keyword, pageSize: 50 }})).data; if (seq === this.shopSequence) { this.shopOptions = data.rows; if (this.model && !this.shopOptions.some(s => String(s.channel_id) === this.channelId)) this.shopOptions.unshift(this.model) } } finally { if (seq === this.shopSequence) this.shopLoading = false } },
    async loadEditor() {
      const seq = ++this.sequence; const channel = this.channelId; this.loading = true; this.error = ''; this.model = null; this.saved = null; this.returnDirty = false; this.addresses = []; this.addressLoading = false
      try {
        const results = await Promise.allSettled([request({ url: `/order/refunds/settings/${channel}` }), request({ url: `/channel/refundPlatform/${channel}/capability` })])
        if (seq !== this.sequence || channel !== this.channelId) return
        if (results[0].status !== 'fulfilled') throw new Error('店铺售后配置读取失败，请重试')
        const base = results[0].value.data
        const intake = { channel_id: Number(channel), revision: 0, enabled: 0, auto_convert: 0, interval_seconds: 30, source_key: '', seller_nick: '', initial_time: parseTime(new Date(Date.now() - 86400000)), ...base.intake }
        const flow = { ...base.flow, small_refund_limit: Number(base.flow.small_refund_limit || 0), payment_limit: Number(base.flow.payment_limit || 0), seller_address_id: String(base.flow.seller_address_id || '') }; delete flow.api_sync
        const access = results[1].status === 'fulfilled' ? { ...results[1].value.data, ignore_code_confirmed: false } : { available: false }
        this.model = { ...base, intake, flow, access, api_sync: { enabled: 0, work_version: 0, ...base.flow.api_sync }, returns: { ...base.returns, merge_mode: !Number(base.returns.enabled) ? 'NONE' : Number(base.returns.auto_enabled) ? 'AUTO' : 'MANUAL' }}; this.saved = clone(this.model)
        this.shopOptions = [this.model]; if (flow.seller_address_id) this.addresses = [{ value: flow.seller_address_id, label: `已配置平台地址（编号${flow.seller_address_id}）` }]
        this.$nextTick(this.loadReturnTab)
      } catch (error) { if (seq === this.sequence) this.error = error.message || '配置读取失败，请重试' } finally { if (seq === this.sequence) this.loading = false }
    },
    async reloadEditor() { if (await this.canDiscard()) this.loadEditor() },
    loadReturnTab() { if (this.tab === 'returns' && this.model) this.$nextTick(() => { if (this.$refs.returns && String(this.$refs.returns.shop.channel_id) !== this.channelId) this.$refs.returns.open(this.model) }) },
    returnPreview(policy) { if (this.model) this.model.returns = clone(policy) },
    returnLoaded(policy) { this.model.returns = clone(policy); this.saved.returns = clone(policy); this.returnDirty = false }, returnSaved() { this.returnDirty = false; this.$emit('changed'); this.$message.info('退货与入库配置已保存，仓库执行仍按单据资料和能力检查') },
    async checkJdp() { this.checking = true; try { await testRefundConfig(Number(this.channelId)); this.$message.success('推送库读取检查通过，未推进同步游标') } finally { this.checking = false } },
    async loadAddresses() { const channel = this.channelId; this.addressLoading = true; this.error = ''; try { const data = (await request({ url: `/order/refunds/flow-configs/${channel}/addresses` })).data; if (channel !== this.channelId || !this.model) return; const rows = []; const walk = (value, depth = 0) => { if (!value || typeof value !== 'object' || depth > 12) return; if (value.contact_id || value.address_id) rows.push({ value: String(value.contact_id || value.address_id), label: [value.contact_name || value.name, value.province, value.city, value.country, value.addr || value.address].filter(Boolean).join(' ') }); Object.values(value).forEach(v => walk(v, depth + 1)) }; walk(data); this.addresses = rows.filter((r, i) => rows.findIndex(x => x.value === r.value) === i); if (!rows.length) this.error = '平台未返回可选地址，请核对平台地址资料' } catch (error) { if (channel === this.channelId) this.error = error.message || '平台地址未取得，请核对查询授权' } finally { if (channel === this.channelId) this.addressLoading = false } },
    openMainAuthorization() { this.$router.push({ path: '/oms-channel/settings', query: { tab: 'shop', channelId: this.channelId }}) },
    async authorizePayment() { this.authorizing = true; const popup = window.open('about:blank', '_blank'); if (popup) popup.opener = null; try { const r = await request({ url: `/channel/refundPlatform/${this.channelId}/payment-authorize`, method: 'post' }); if (popup) popup.location.href = r.data.url; else this.$message.warning('浏览器阻止了授权窗口，请允许弹窗后重试') } catch (error) { if (popup) popup.close(); throw error } finally { this.authorizing = false } },
    async save() {
      if (!this.dirty || this.saving || !Number(this.model.shop_enabled)) return; const channel = this.channelId; this.saving = true; this.error = ''; let partiallySaved = false
      try {
        if (this.tab === 'intake') {
          if (JSON.stringify(this.model.intake) !== JSON.stringify(this.saved.intake)) { const p = this.model.intake; if (!p.source_key || !p.seller_nick || !p.initial_time) throw new Error('请先填写推送库、卖家昵称和首次同步时间'); await saveRefundConfig(p); p.revision = Number(p.revision || 0) + 1; this.saved.intake = clone(p); partiallySaved = true }
          if (Number(this.model.api_sync.enabled) !== Number(this.saved.api_sync.enabled)) { await request({ url: `/order/refunds/settings/${channel}/api-sync`, method: 'post', data: { enabled: this.model.api_sync.enabled, work_version: this.model.api_sync.work_version }}); this.saved.api_sync = clone(this.model.api_sync) }
        } else if (this.tab === 'authorization') { await request({ url: `/channel/refundPlatform/${channel}/access`, method: 'post', data: this.model.access }) } else { await request({ url: `/order/refunds/flow-configs/${channel}`, method: 'post', data: this.model.flow }) }
        this.$message.success(`${this.currentTabLabel}已保存，请核对生效条件`); await this.loadEditor(); this.$emit('changed')
      } catch (error) { this.error = (partiallySaved ? 'JDP接入已保存；其余设置未保存。' : '') + (error.message || '保存失败，请核对配置后重试') } finally { this.saving = false }
    }
  }
}
</script>
